# The duo trips: 7 destinations x 2 plans (Slow, Fuller), Sat 31 Oct -> Fri 6 Nov together.
# Money in euros. rooms = price per ROOM per night for the two of you (private room).
# meals=True means dinner + breakfast are included in the room price (shukubo, minshuku, ryokan).
# transport_pp / activities_pp are per person; shared = taxis and private cars, split between you.
# Each day: t title, e effort (Travel/Easy/Active/Big day), am/pm/eve, sleep, wx (forecast base), tr [mode, leg, minutes], b (if it rains)


def D(t, e, am, pm, eve, sleep, wx, tr, b=None):
    return {"t": t, "e": e, "am": am, "pm": pm, "eve": eve, "sleep": sleep, "wx": wx, "tr": tr, "b": b}


def N(place, room, meals=False):
    return {"place": place, "room": room, "meals": meals}


